import{_ as i,o as n,c as t,a2 as a}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"Les Règles de Navigation Interplans","description":"","frontmatter":{},"headers":[],"relativePath":"fr/81-位面穿梭规则.md","filePath":"fr/81-位面穿梭规则.md"}'),s={name:"fr/81-位面穿梭规则.md"};function r(l,e,o,d,u,c){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="les-regles-de-navigation-interplans" tabindex="-1">Les Règles de Navigation Interplans <a class="header-anchor" href="#les-regles-de-navigation-interplans" aria-label="Permalink to &quot;Les Règles de Navigation Interplans&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>81</td></tr><tr><td>Module</td><td>Interaction interplans et règles temporelles</td></tr><tr><td>Mots clés</td><td>navigation interplans, permis de navigation, seuils énergétiques, étalonnage de l&#39;Ancre, prévention et contrôle de la pollution</td></tr></tbody></table><h2 id="i-le-positionnement-juridique-de-la-navigation" tabindex="-1">I. Le Positionnement Juridique de la Navigation <a class="header-anchor" href="#i-le-positionnement-juridique-de-la-navigation" aria-label="Permalink to &quot;I. Le Positionnement Juridique de la Navigation&quot;">​</a></h2><p>La navigation interplans désigne le comportement par lequel un individu ou un groupe d&#39;êtres vivants franchit une barrière de lois pour passer d&#39;un plan à un autre, par des moyens techniques ou des capacités de culture. Dans le cadre juridique de la Civilisation Symbiotique de l&#39;Ancre, la navigation interplans relève du « comportement spécial à haut risque » et doit être soumise à une gestion stricte des permis et à une supervision du processus. L&#39;article 47 de la Constitution Symbiotique stipule clairement : « Aucune organisation ni aucun individu ne peut effectuer de navigation interplans sans autorisation, ni utiliser la navigation interplans pour se livrer à des activités de prédation, d&#39;ingérence ou de pollution contre la civilisation d&#39;autres plans. »</p><p>La raison fondamentale pour laquelle la navigation interplans exige un contrôle strict est que le comportement de navigation lui-même peut causer de multiples impacts sur le plan cible : perturbation des lois, injection d&#39;énergie, pollution de la conscience, invasion microbienne et ingérence culturelle. Ces impacts peuvent, au plus léger, déclencher des anomalies locales dans le plan cible, et au pire, modifier sa trajectoire d&#39;évolution civilisationnelle, voire provoquer l&#39;effondrement de ses lois. Par conséquent, l&#39;objectif central des règles de navigation est de « maintenir l&#39;impact externe du comportement de navigation dans un seuil acceptable ».</p><h2 id="ii-le-systeme-hierarchique-des-permis-de-navigation" tabindex="-1">II. Le Système Hiérarchique des Permis de Navigation <a class="header-anchor" href="#ii-le-systeme-hierarchique-des-permis-de-navigation" aria-label="Permalink to &quot;II. Le Système Hiérarchique des Permis de Navigation&quot;">​</a></h2><p>L&#39;Univers Hengyuan applique un système hiérarchique des permis de navigation interplans, divisant les permis en quatre niveaux selon le but de la navigation, le type de plan cible et les qualifications du navigateur :</p><table tabindex="0"><thead><tr><th>Niveau de permis</th><th>Scénario applicable</th><th>Organe d&#39;approbation</th><th>Validité</th><th>Conditions additionnelles</th></tr></thead><tbody><tr><td>Niveau A (Observation archéologique)</td><td>Archéologie purement observationnelle, aucun contact physique</td><td>Administration des Plans</td><td>Mission unique</td><td>Doit adopter le schéma Miroir de Réplication + espace isolé</td></tr><tr><td>Niveau B (Échange académique)</td><td>Échange limité de connaissances avec la civilisation du plan cible</td><td>Administration des Plans + Ministère de la Culture</td><td>Un an maximum</td><td>Un accord de non-ingérence mutuelle doit être signé</td></tr><tr><td>Niveau C (Collaboration de ressources)</td><td>Collaboration de ressources et de technologies sur la base de l&#39;égalité et du bénéfice mutuel</td><td>Approbation spéciale de l&#39;Assemblée Délibérante de l&#39;Ancre</td><td>Trois ans maximum</td><td>Doit obtenir le consentement de la civilisation du plan cible</td></tr><tr><td>Niveau D (Intervention d&#39;urgence)</td><td>Intervention humanitaire lorsque le plan cible fait face à une crise de niveau extinctif</td><td>Résolution d&#39;urgence de l&#39;Assemblée Délibérante de l&#39;Ancre</td><td>Durée de la crise</td><td>Un rapport d&#39;intervention complet doit être soumis après coup</td></tr></tbody></table><p>Les permis de navigation de tout niveau interdisent les comportements suivants : piller l&#39;énergie d&#39;origine du plan cible, imposer de force l&#39;idéologie de son propre plan, procéder à des modifications génétiques ou de conscience sans consentement, établir des bases militaires permanentes dans le plan cible, et toute forme de domination coloniale.</p><h2 id="iii-exigences-techniques-et-seuils-energetiques-de-la-navigation" tabindex="-1">III. Exigences Techniques et Seuils Énergétiques de la Navigation <a class="header-anchor" href="#iii-exigences-techniques-et-seuils-energetiques-de-la-navigation" aria-label="Permalink to &quot;III. Exigences Techniques et Seuils Énergétiques de la Navigation&quot;">​</a></h2><p>La navigation interplans doit satisfaire des conditions techniques strictes. Premièrement, le navigateur doit posséder une culture supérieure au troisième niveau (le Stade Huàkōng) du « système de régulation des principes juridiques spatiaux », ou embarquer dans un véhicule de navigation interplans conforme aux normes. Deuxièmement, le point de départ et le point d&#39;arrivée de la navigation doivent tous deux disposer d&#39;une Ancre pour l&#39;étalonnage des coordonnées ; la navigation aveugle sans positionnement par l&#39;Ancre est strictement interdite.</p><p>La consommation d&#39;énergie du processus de navigation est proportionnelle à la force de la barrière de lois du plan cible. L&#39;Univers Hengyuan a établi un « tableau standardisé des seuils énergétiques de navigation ». L&#39;énergie minimale requise pour la navigation vers différents types de plans est la suivante :</p><ul><li>Plan à Dominante Matérielle : 1 000 unités d&#39;énergie standard</li><li>Plan à Énergie Manifestée : 5 000 unités d&#39;énergie standard</li><li>Plan à Dominante de Conscience : 20 000 unités d&#39;énergie standard</li><li>Plan aux Lois Fragmentées : 50 000 unités d&#39;énergie standard (avec un taux de succès inférieur à 30 %)</li><li>Plan Proche de l&#39;Origine : valeur théorique supérieure à 100 000 ; aucun succès enregistré à ce jour</li></ul><p>L&#39;énergie de navigation doit être transportée par le navigateur ou le véhicule lui-même ; il est interdit d&#39;extraire de l&#39;énergie du plan cible pour le processus de navigation. Cette disposition vise à empêcher que la navigation ne cause une prédation énergétique sur le plan cible.</p><h2 id="iv-prevention-et-controle-de-la-pollution-dans-le-processus-de-navigation" tabindex="-1">IV. Prévention et Contrôle de la Pollution dans le Processus de Navigation <a class="header-anchor" href="#iv-prevention-et-controle-de-la-pollution-dans-le-processus-de-navigation" aria-label="Permalink to &quot;IV. Prévention et Contrôle de la Pollution dans le Processus de Navigation&quot;">​</a></h2><p>L&#39;un des plus grands risques de la navigation interplans est la « pollution interplans », comprenant la pollution biologique (introduire des microorganismes de son propre plan dans le plan cible), la pollution énergétique (l&#39;ingérence des résidus d&#39;énergie de son propre plan avec les lois du plan cible) et la pollution de la conscience (l&#39;influence des fluctuations de conscience du navigateur sur le domaine de conscience du plan cible).</p><p>Pour prévenir et contrôler la pollution, tous les navigateurs doivent accomplir la « procédure de purification en trois niveaux » avant le départ :</p><ol><li><strong>Purification biologique</strong> : effectuer 72 heures de dépistage et d&#39;élimination des microorganismes dans un espace isolé, pour garantir l&#39;absence de tout pathogène de son propre plan.</li><li><strong>Purification énergétique</strong> : ajuster la fréquence énergétique du navigateur à une plage compatible avec le plan cible grâce au dispositif d&#39;étalonnage de l&#39;Ancre, réduisant les réactions de répulsion énergétique.</li><li><strong>Purification de la conscience</strong> : suivre un entraînement de blindage de la conscience pour garantir qu&#39;aucune fluctuation de pensée susceptible d&#39;interférer avec le domaine de conscience du plan cible ne soit activement émise pendant la navigation.</li></ol><p>En outre, le champ d&#39;activité du navigateur dans le plan cible est strictement limité à la « zone délimitée par le permis de navigation », et toute dispersion non autorisée est interdite. Après son retour dans son propre plan, le navigateur doit de nouveau subir une observation en quarantaine, d&#39;une durée d&#39;au moins 30 jours convertis selon la vitesse temporelle du plan cible.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Les règles de navigation interplans sont la première ligne de défense de sécurité de l&#39;interaction interplans. À travers le triple mécanisme de la classification des permis, des seuils techniques et de la prévention et du contrôle de la pollution, elles garantissent que la navigation se déroule toujours sur la voie de « faible impact, traçabilité et responsabilité ». Le but ultime des règles n&#39;est pas de restreindre les échanges entre civilisations, mais de faire en sorte que les échanges se produisent de manière symbiotique, et non de manière prédatrice.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>80-位面理论与分类 (La Théorie des Plans et la Classification)</li><li>88-跨位面伦理准则 (Les Normes Éthiques Interplans)</li><li>62-空间法理技术实现 (La Mise en Œuvre Technologique des Principes Juridiques Spatiaux)</li></ul>',23)])])}const m=i(s,[["render",r]]);export{g as __pageData,m as default};
